#!/usr/bin/env python3
"""Fermionic Gaussian determinant/propagator bridge of the physical history kernel."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
src=json.loads((ROOT/'research/nima/results/nnmhv-kernel-wall-tail-boundary.json').read_text());K=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_matrix']]);K0=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_without_upper_boundary_transport']]);B=K-K0;t=s.symbols('t');Kt=K0+t*B;Z=s.factor(Kt.det());ward=s.factor(s.diff(Z,t)-Z*s.trace(Kt.inv()*B));ratio=s.factor(K.det()/K0.det());checks={'fermionic_partition_nonzero':K.det()!=0 and K0.det()!=0,'jacobi_logdet_identity':ward==0,'propagator_is_inverse':s.simplify(K*K.inv())==s.eye(3),'boundary_is_diagonal_self_energy':all(B[i,j]==0 for i in range(3) for j in range(3) if i!=j),'long_propagator_sign_flips':s.sign(K0.inv()[2,0])==1 and s.sign(K.inv()[2,0])==-1,'triangular_partition_factorizes':s.factor(K.det()-s.prod(K[i,i] for i in range(3)))==0}
out={'schema':'marici.nima.nnmhv-fermionic-gaussian-bridge.v1','action':'S_F=bar(psi) K psi','partition_function':'Z_F=int dbar(psi)dpsi exp(-S_F)=det K','two_point_function':'<psi_i bar(psi)_j>=(K^-1)_(i,j)','boundary_deformation':'K(t)=K0+tB with diagonal B','ward_identity':'d_t log det K(t)=Tr(K(t)^-1 B)','determinant_ratio_with_vs_without_boundary':str(ratio),'long_propagator_without_boundary':str(s.factor(K0.inv()[2,0])),'long_propagator_with_boundary':str(s.factor(K.inv()[2,0])),'checks':{k:bool(v) for k,v in checks.items()},'passed':all(bool(v) for v in checks.values()),'meaning':'The history kernel can serve exactly as a nonsymmetric fermionic quadratic operator. Boundary transport is a diagonal self-energy/mass insertion; its determinant response obeys Jacobi’s identity, and its propagator is the inverse path sum whose long-range sign flips.','bridges':['Berezin Gaussian integration','fermionic determinants','Green functions and propagators','self-energy/mass insertions','log-determinant response identity']};p=ROOT/'research/nima/results/nnmhv-fermionic-gaussian-bridge.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
